import { randomUUID } from 'node:crypto';
import type { Request, RequestHandler, Response } from 'express';
import { runWithLogContext } from '../logging/context.ts';
import type { Logger } from '../logging/logger.ts';
import type { AppMetrics } from '../metrics/appMetrics.ts';

/**
 * Gives every request an id (returned as X-Request-Id and included in every error body), makes
 * that id part of EVERY log line written while the request runs (see logging/context.ts), records
 * the request in the metrics, and logs one line when the response finishes. The id is always
 * generated by the server: a client-supplied id could be used to forge log entries. Only method,
 * path (no query string) and status are logged, never headers or bodies.
 */
export function requestContext(logger: Logger, metrics?: AppMetrics): RequestHandler {
  return (req, res, next) => {
    const requestId = randomUUID();
    res.locals['requestId'] = requestId;
    res.setHeader('X-Request-Id', requestId);
    const startedAt = process.hrtime.bigint();
    res.on('finish', () => {
      const seconds = Number(process.hrtime.bigint() - startedAt) / 1e9;
      const durationMs = seconds * 1000;
      const route = routeLabel(req);
      if (metrics) {
        metrics.httpRequests.inc({
          route,
          method: req.method,
          status_class: `${String(Math.floor(res.statusCode / 100))}xx`,
        });
        metrics.httpDuration.observe(seconds, { route });
      }
      // Health checks and scrapes run every few seconds: debug level keeps real traffic readable.
      const noisy = route.startsWith('/health') || route === '/metrics';
      logger[noisy ? 'debug' : 'info']('request', {
        method: req.method,
        path: req.path,
        status: res.statusCode,
        durationMs: Math.round(durationMs * 10) / 10,
      });
    });
    runWithLogContext({ requestId }, next);
  };
}

/**
 * The route PATTERN ("/auctions/:auctionId/bids"), never the raw path: raw paths contain ids and
 * would create one metric series per auction. Unmatched requests share one label so a scanner
 * cannot create series by requesting random URLs.
 */
export function routeLabel(req: Request): string {
  const pattern: unknown = req.route && (req.route as { path?: unknown }).path;
  return typeof pattern === 'string' ? `${req.baseUrl}${pattern}` : 'unmatched';
}

export function getRequestId(res: Response): string {
  const id: unknown = res.locals['requestId'];
  return typeof id === 'string' ? id : 'unknown';
}
